<?php declare(strict_types=1);require_once __DIR__.'/../includes/admin-auth.php';$releases=load_json('releases.json',[]);$error='';$message='';if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['action'])){require_csrf();$id=sanitize($_POST['id']??'');$action=sanitize($_POST['action']??'');if($id&&in_array($action,['publish','unpublish','latest','delete'],true)){if($action==='delete'){if(delete_json_item('releases.json',fn($r)=>is_array($r)&&($r['id']??'')===$id))$message='Release deleted.';else$error='Release could not be deleted.';}else{$updated=update_json('releases.json',fn($list)=>array_map(fn($r)=>is_array($r)&&($r['id']??'')===$id?array_merge($r,['is_published'=>$action==='publish','is_latest'=>$action==='latest']):$r,$list));if($updated){$message=$action==='publish'?'Release published.':($action==='unpublish'?'Release unpublished.':'Latest release updated.');}else$error='Release could not be updated.';}}}?>
